// The HTTP node before this ran once per course and answers in the same
// order, so item i belongs to course i. The course is taken from there
// rather than from the answer, which does not carry it.
const courses = $('List courses').all();
const results = [];

$input.all().forEach((item, i) => {
  const course_id = courses[i]?.json?.course_id;
  if (!course_id) return;

  const groups = item.json?.data?.Aggregate?.ChatHistory || [];
  for (const g of groups) {
    const user_id = g.groupedBy?.value;
    if (!user_id) continue;

    results.push({ json: {
      course_id,
      user_id,
      // Both halves of the key. Filtering on the learner alone returns
      // whichever course's record Weaviate finds first, and limit: 1 makes
      // that silent.
      // Every record, not the first. There should be exactly one per pair;
      // there were ten, because a broken delete left the previous one behind
      // on every run and limit: 1 hid them all but one. The run replaces all
      // of them, so it has to see all of them.
      um_query_body: {
        query: `{ Get { UserMemory(
          where: { operator: And operands: [
            { path: ["user_id"]   operator: Equal valueText: ${JSON.stringify(String(user_id))} }
            { path: ["course_id"] operator: Equal valueText: ${JSON.stringify(String(course_id))} }
          ] }
          sort: [{ path: ["last_updated"], order: desc }]
          limit: 50
        ) { _additional { id } user_id course_id concepts_mastered concepts_struggling open_questions learning_patterns summary last_updated chapter } } }`
      }
    }});
  }
});

return results;

const response = $input.item.json;
const { user_id, course_id } = $('Extract user_ids').item.json;
const found = response?.data?.Get?.UserMemory || [];

// Every record that exists for this learner in this course. All of them are
// replaced by the one this run writes, so all of their ids are stale — the
// duplicates that a failed delete left behind included.
const stale_ids = found.map(m => m._additional?.id).filter(Boolean);

// The newest one is the only one whose cursor can be trusted: an older
// duplicate carries an older last_updated, and starting from that would
// summarise the same messages again. The query sorts descending, but the
// sort is repeated here so the choice does not depend on it.
const newest = found.slice().sort(
  (a, b) => new Date(b.last_updated || 0) - new Date(a.last_updated || 0)
)[0] || null;

let last_updated = '1970-01-01T00:00:00.000Z';
let existing = {
  concepts_mastered: [],
  concepts_struggling: [],
  open_questions: [],
  learning_patterns: '',
  summary: ''
};

if (newest) {
  last_updated = newest.last_updated || '1970-01-01T00:00:00.000Z';
  existing = {
    concepts_mastered: newest.concepts_mastered || [],
    concepts_struggling: newest.concepts_struggling || [],
    open_questions: newest.open_questions || [],
    learning_patterns: newest.learning_patterns || '',
    summary: newest.summary || ''
  };
}

// The cursor is per course as well. Shared, a learner active in one course
// would move the other course's cursor past messages that are then never
// summarised.
const ch_query_body = {
  query: `{ Get { ChatHistory(
    where: { operator: And operands: [
      { path: ["user_id"]   operator: Equal valueText: ${JSON.stringify(String(user_id ?? ''))} }
      { path: ["course_id"] operator: Equal valueText: ${JSON.stringify(String(course_id ?? ''))} }
      { path: ["timestamp"] operator: GreaterThan valueText: ${JSON.stringify(String(last_updated ?? ''))} }
    ] }
    sort: [{ path: ["timestamp"], order: asc }]
    limit: 500
  ) { user_id course_id role text timestamp chapter concepts_mentioned } } }`
};

return {
  json: {
    user_id,
    course_id,
    stale_ids,
    // Which of them is the one worth keeping, for the path that does not
    // write: a pair with nothing new to summarise still has to lose its
    // duplicates, and this is the record they are duplicates of.
    newest_id: newest?._additional?.id || null,
    last_updated,
    existing,
    ch_query_body
  }
};

const response = $input.item.json;
const vars = $('Process Memory').item.json;
const { user_id, course_id, stale_ids, newest_id, existing } = vars;
const chatData = response?.data?.Get?.ChatHistory || [];

// [A] Keine neuen Messages
if (chatData.length === 0) {
  return { json: { skip: true, reason: 'no_new_messages', user_id, course_id,
                 stale_ids, newest_id } };
}

// [B] Session noch aktiv (< 30 Min Inaktivität)
const timestamps = chatData.map(m => new Date(m.timestamp).getTime());
const maxTimestamp = Math.max(...timestamps);
const diffMin = (Date.now() - maxTimestamp) / 60000;
if (diffMin < 30) {
  return { json: { skip: true, reason: 'session_active', user_id, course_id,
                 stale_ids, newest_id, inactive_min: Math.round(diffMin) } };
}

const maxChapter = Math.max(...chatData.map(m => m.chapter || 0));

const messagesText = chatData
  .map(m => m.role === 'user'
    ? `[user]: ${m.text}`
    : `[assistant]: ${m.text.slice(0, 200)}`)
  .join('\n');

return {
  json: {
    skip: false,
    user_id,
    course_id,
    stale_ids,
    newest_id,
    existing,
    max_chapter: maxChapter,
    last_updated_now: new Date().toISOString(),
    messagesText
  }
};

// The id of a learning record is derived from the pair it belongs to, so
// there can only ever be one. Before this, Weaviate assigned a random id on
// every write and the previous record was removed afterwards by a separate
// DELETE — which failed silently for weeks (its URL contained an
// unevaluated expression), leaving one duplicate per run: ten for the most
// active learner. A delete that has to succeed for the data to be correct is
// the wrong shape; an id that cannot be duplicated is the right one.
let crypto;
try {
  crypto = require('crypto');
} catch (e) {
  throw new Error(
    'This workflow needs the crypto module in Code nodes. Add "crypto" to ' +
    'NODE_FUNCTION_ALLOW_BUILTIN on the n8n service in docker/docker-compose.yml ' +
    'and recreate the container: docker compose up -d smartrag-n8n'
  );
}

// A fixed namespace for this project, so the same pair always maps to the
// same id — on this installation, on the next one, and from any client that
// computes it the same way (this is RFC 4122 version 5, what Weaviate's own
// clients call generateUuid5).
const NAMESPACE = '6f2b1e34-8c4a-5f7d-9b21-4a7e0d3c5f18';

function uuid5(namespace, name) {
  const ns = Buffer.from(namespace.replace(/-/g, ''), 'hex');
  const hash = crypto.createHash('sha1')
    .update(Buffer.concat([ns, Buffer.from(String(name), 'utf8')]))
    .digest();
  const b = Buffer.from(hash.subarray(0, 16));
  b[6] = (b[6] & 0x0f) | 0x50;   // version 5
  b[8] = (b[8] & 0x3f) | 0x80;   // RFC 4122 variant
  const hex = b.toString('hex');
  return [hex.slice(0, 8), hex.slice(8, 12), hex.slice(12, 16),
          hex.slice(16, 20), hex.slice(20)].join('-');
}

const response = $input.item.json;
const vars = $('Check and Prepare').item.json;
const { user_id, course_id, stale_ids, existing, max_chapter, last_updated_now } = vars;

// Refused rather than written with an empty course. A record nobody can
// retrieve is a bug that hides; one written under the wrong course is a bug
// that shows up as another course's learner data.
if (!course_id) {
  return { json: { parse_error: true, error_reason: 'no_course', user_id,
                   course_id, raw_preview: '' } };
}

// OpenAI-compatible chat/completions shape, which is what every provider
// this project supports speaks. The node before this was an Anthropic node
// with a hard-coded model, so on an installation configured for any other
// provider it could not run at all — and the parser read content[0].text,
// which only Anthropic returns.
const raw = response?.choices?.[0]?.message?.content || '';

// Thinking-Tags entfernen (falls Modell trotzdem denkt)
const cleaned = raw.replace(/<think>[\s\S]*?<\/think>/gi, '').trim();

// JSON extrahieren
const jsonMatch = cleaned.match(/\{[\s\S]*\}/);
if (!jsonMatch) {
  return {
    json: {
      parse_error: true,
      error_reason: 'no_json_found',
      user_id,
      course_id,
      raw_preview: raw.substring(0, 300)
    }
  };
}

let parsed;
try {
  parsed = JSON.parse(jsonMatch[0]);
} catch(e) {
  return {
    json: {
      parse_error: true,
      error_reason: 'json_parse_failed',
      user_id,
      course_id,
      error: e.message,
      raw_preview: cleaned.substring(0, 300)
    }
  };
}

// REPLACE: concepts_mastered (nur aktuelle Session, max. 5)
const newMastered = parsed.concepts_mastered || [];

// REPLACE: concepts_struggling (nur aktuelle Session, max. 5), REMOVE wenn auch in mastered
const newStruggling = (parsed.concepts_struggling || [])
  .filter(c => !newMastered.includes(c));

// open_questions: REPLACE (aktuelle Session)
const newOpenQuestions = parsed.open_questions || [];

// learning_patterns: LLM konsolidiert (REPLACE, enthält Historie)
const newLearningPatterns = parsed.learning_patterns || existing.learning_patterns || '';

// summary: REPLACE (aktuelle Session)
const newSummary = parsed.summary || '';

const object_id = uuid5(NAMESPACE, `${course_id}::${user_id}`);

return {
  json: {
    parse_error: false,
    user_id,
    course_id,
    object_id,
    // Everything that is there now, so the write can clear the ground first.
    stale_ids: stale_ids || [],
    weaviate_object: {
      class: 'UserMemory',
      id: object_id,
      properties: {
        // The course this record belongs to, carried down from the loop
        // rather than read from the environment. The environment holds the
        // installation's single course, which is exactly what stopped there
        // being more than one.
        course_id,
        user_id,
        concepts_mastered: newMastered,
        concepts_struggling: newStruggling,
        open_questions: newOpenQuestions,
        learning_patterns: newLearningPatterns,
        summary: newSummary,
        chapter: max_chapter || 0,
        last_updated: last_updated_now
      }
    }
  }
};

const response = $input.item.json;
const mergeVars = $('Parse and Merge').item.json;
const { user_id, course_id, object_id } = mergeVars;

if (!response?.id) {
  return {
    json: {
      post_ok: false,
      user_id,
      course_id,
      error: 'POST to Weaviate returned no ID',
      response_preview: JSON.stringify(response).substring(0, 200)
    }
  };
}

// The id Weaviate reports back must be the one that was asked for. If it is
// not, the object was stored under an id nothing will find again, and the
// next run would write a second one beside it.
if (response.id !== object_id) {
  return {
    json: {
      post_ok: false,
      user_id,
      course_id,
      error: `Weaviate stored the record as ${response.id}, not ${object_id}`
    }
  };
}

return {
  json: {
    post_ok: true,
    user_id,
    course_id,
    object_id: response.id
  }
};

