parameters.jsCode:
// One record per learner per course, so the loop has to run over courses
// first. It used to run over learners alone: a learner in two courses got a
// single record in which both courses' concepts were merged, and it was
// written with the installation's single course from the environment.
const groups = $input.first().json?.data?.Aggregate?.ChatHistory || [];
const out = [];

for (const g of groups) {
  const course_id = g.groupedBy?.value;
  // Messages written before the sync carried the course have an empty one.
  // They are left out rather than folded into whichever course comes first:
  // a learning record is about one course, and a wrong one is invisible.
  if (!course_id) continue;

  out.push({ json: {
    course_id,
    users_query_body: {
      query: `{ Aggregate { ChatHistory(
        where: { path: ["course_id"] operator: Equal valueText: ${JSON.stringify(String(course_id))} }
        groupBy: "user_id"
      ) { groupedBy { value } meta { count } } } }`
    }
  }});
}

if (out.length === 0) {
  console.log('No course has any chat history yet — nothing to summarise.');
}
return out;

// Clear the ground before writing. Weaviate refuses a POST whose id already
// exists, so removing the derived id is what makes the write an upsert; the
// stale ids are the duplicates a previous version left behind, and they go at
// the same time.
//
// The order is deliberate: delete, then write. If the write then fails, the
// pair has no record at all — and the next run starts its cursor at 1970 and
// rebuilds it from that course's whole history. The opposite order is what
// produced the duplicates: a write followed by a delete that has to succeed.
const WEAVIATE = `http://smartrag-weaviate:${$env.WEAVIATE_HTTP_PORT || 8080}`;
const KEY = $env.WEAVIATE_API_KEY || '';
const results = [];

for (const item of $input.all()) {
  const ids = [...new Set([item.json.object_id, ...(item.json.stale_ids || [])])]
    .filter(Boolean);

  let removed = 0;
  let absent = 0;

  for (const id of ids) {
    // ignoreHttpStatusErrors + returnFullResponse rather than a try/catch:
    // a Code node runs in a task runner, and a thrown error loses its
    // structured fields across that process boundary — the status code is
    // exactly what has to be read here, since 404 is the normal case on a
    // first run.
    const res = await this.helpers.httpRequest({
      method: 'DELETE',
      url: `${WEAVIATE}/v1/objects/UserMemory/${id}`,
      headers: { Authorization: `Bearer ${KEY}` },
      returnFullResponse: true,
      ignoreHttpStatusErrors: true,
    });

    if (res.statusCode === 404) { absent++; continue; }
    if (res.statusCode >= 400) {
      // Not swallowed: carrying on would write a second record beside one
      // that is still there, which is the bug this replaces.
      throw new Error(
        `Could not remove the previous learning record ${id}: HTTP ${res.statusCode}`
      );
    }
    removed++;
  }

  results.push({ json: { ...item.json, removed, absent } });
}

return results;

// Nothing to summarise for this pair — but its duplicates are still there,
// and skipping is the normal state for a learner who has stopped writing in
// a course. Left alone they would never go: the write path is the only thing
// that used to clear them, and it does not run here. So a pair that is
// skipped still loses everything except the record it is skipping on.
//
// The kept record keeps its old, randomly assigned id. That is fine: it is
// found by its properties, and the next run that actually writes replaces it
// with the derived one.
const WEAVIATE = `http://smartrag-weaviate:${$env.WEAVIATE_HTTP_PORT || 8080}`;
const KEY = $env.WEAVIATE_API_KEY || '';
const results = [];

for (const item of $input.all()) {
  const keep = item.json.newest_id;
  const extras = (item.json.stale_ids || []).filter(id => id && id !== keep);

  let removed = 0;
  for (const id of extras) {
    const res = await this.helpers.httpRequest({
      method: 'DELETE',
      url: `${WEAVIATE}/v1/objects/UserMemory/${id}`,
      headers: { Authorization: `Bearer ${KEY}` },
      returnFullResponse: true,
      ignoreHttpStatusErrors: true,
    });
    // 404 means somebody else got there first, which is the desired state.
    if (res.statusCode === 404) continue;
    if (res.statusCode >= 400) {
      // Reported, not thrown: this run had nothing to write anyway, and
      // failing it would turn a tidy-up into a red execution that hides the
      // reason the pair was skipped.
      console.log(`Could not remove duplicate ${id}: HTTP ${res.statusCode}`);
      continue;
    }
    removed++;
  }

  if (removed > 0) {
    console.log(`${item.json.course_id}/${item.json.user_id}: removed ${removed} duplicate record(s).`);
  }
  results.push({ json: { ...item.json, duplicates_removed: removed } });
}

return results;
